import React, { useEffect, useState } from 'react';

function Catalog({ token, user }) {
  const [apps, setApps] = useState([]);
  const [error, setError] = useState('');

  useEffect(() => {
    fetch('http://localhost:8000/apps', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(setApps)
      .catch(() => setError('Error cargando catálogo.'));
  }, [token]);

  const runApp = async (id) => {
    try {
      await fetch(`http://localhost:8000/apps/${id}/run`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` }
      });
      alert('Aplicación/juego lanzado.');
    } catch {
      alert('No tienes permiso o hubo un error.');
    }
  };

  return (
    <div className="catalog-container">
      <h2>Catálogo</h2>
      {error && <div className="error">{error}</div>}
      <div className="apps-grid">
        {apps.map(app => (
          <div className="app-card" key={app.id}>
            <h3>{app.title}</h3>
            <p>{app.category}</p>
            <p>{app.description}</p>
            <button onClick={() => runApp(app.id)} disabled={!user.is_admin && !app.allowed_users.includes(user.username)}>
              Ejecutar
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Catalog;
